//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::uint::uint64_to_nat`; the
//! native twin is `benches/native/Bench/Uint64ToNat.lean`.
//! operands below 2^63, so the Nat is a scalar on both sides (a Nat word)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::uint;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(acc, nat_unbox(nat_box(uint::uint64_to_nat(x >> 1))));
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
